SAFETY_VIZ = v.figure(
    720, 170,
    [v.box(10, 20, 200, 56, "Local only", "ok", "rewrite freely: amend, rebase, reset"),
     v.arrow(210, 48, 260, 48, "git push"), v.box(260, 20, 200, 56, "Shared (pushed)", "warn", "add commits: revert, merge"),
     v.arrow(460, 48, 510, 48), v.box(510, 20, 200, 56, "Protected main", "ink", "reviewed, never rewritten"),
     v.text(360, 108, "Rule: history that others may have must only ever grow.", "dg-s"),
     v.text(360, 128, "Rewrite (rebase, reset, amend, force-push) only what is still yours alone.", "dg-s")],
    "When rewriting history is safe", "The safety line: rewrite local history, only add to shared history")

